func validateNotBeingUsedByTemplate(ctx context.Context, assetId string, kind api.AssetKind) *api.Error {
	//
	//   validation that asset not being used by templates
	//
	templates, listError := dao.ListTemplatesUsingAssetId(ctx, assetId)
	if listError != nil {
		return listError
	}
	if len(templates) != 0 {
		return composeBeingInUseMessage("template", namesOfAssets(templates), kind, assetId)
	}

	return nil
}

func namesOfAssets(assets []dbmodel.AssetMeta) []string {
	result := make([]string, 0, len(assets))
	for _, asset := range assets {
		result = append(result, asset.Name)
	}
	return result
}

func composeBeingInUseMessage(resourceKind string, resourceNames []string, assetKind api.AssetKind, _ /*assetId*/ string) *api.Error {
	msg := fmt.Sprintf("the requested %s asset is being used by ", assetKind)
	if len(resourceNames) == 1 {
		msg += fmt.Sprintf("%s '%s'", resourceKind, resourceNames[0])
	} else {
		etc := ""
		if len(resourceNames) > 2 {
			etc = ", etc."
		}
		msg += fmt.Sprintf("%d %ss (%s, %s%s)", len(resourceNames), resourceKind, resourceNames[0], resourceNames[1], etc)
	}
	return api.NewError(http.StatusPreconditionFailed, msg, nil)
}
